import { Component, h, Prop, Host, Element, ComponentInterface } from '@stencil/core';
import classnames from 'classnames';
import { SpinnerSize, SpinnerLayout, SpinnerColor } from './types';
import { Slot, Slots } from '@src/framework/decorators';
import { KsIconLoading } from '@fe-infra/keystone-icons-stencil';

const prefix = 'spinner';

/**
 * @slot default - Slot for custom content to be displayed after the spinner finished its loading, will also enable its container mode.
 * @slot indicator - Slot for customizing the indicator icon.
 * @slot description - Slot for the description text displayed alongside the indicator.
 * @part backdrop - The backdrop element.
 * @part feedback - The feedback wrapper that contains the indicator and description.
 */
@Component({
  tag: 'ks-spinner',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSpinner implements ComponentInterface {
  @Element() el!: HTMLKsSpinnerElement;

  /** The color of the loading spinner. Can be one of the following values: `"primary"` or `"ai"`. */
  @Prop() color?: SpinnerColor = 'primary';

  /**
   * @deprecated Use `color="inverse"` instead. This prop will be removed in a future version.
   * Indicates whether the loading spinner should use an inverse color scheme. When `true`, the spinner will display in inverse colors.
   */
  @Prop() inverse = false;
  /** The size of the loading spinner. Can be either `"md"` or `"lg"`. */
  @Prop() size?: SpinnerSize = 'md';
  /** The layout orientation of the loading spinner. Can be either `vertical` or `horizontal`. */
  @Prop() layout?: SpinnerLayout = 'horizontal';
  /** Indicates whether the loading spinner should be displayed. When `true`, the spinner is shown. */
  @Prop() loading?: boolean = true;
  /** Indicates whether the loading spinner should be displayed fullscreen. When `true`, the spinner is shown fullscreen. */
  @Prop() fullscreen?: boolean = false;

  /** Whether to automatically center the indicator within the container or fullscreen overlay. When `true`, the indicator is centered. When `false`, the indicator is placed at the top-left corner of the container or overlay. */
  @Prop() centerIndicator = true;

  /** When set to `true`, adds a semi-transparent backdrop behind the spinner to dim the underlying content. */
  @Prop() backdrop = false;

  /** Default slot: when content is provided, spinner switches to container mode; otherwise it renders inline mode with indicator and description. */
  @Slot({ slotname: '_default' }) private defaultSlot!: Slots;

  /** Slot for customizing the indicator icon. */
  /* indicator slot is consumed in render via <slot name="indicator"> */

  /** Slot for the description text displayed alongside the indicator. */
  /* description slot is consumed in render via <slot name="description"> */

  render() {
    const isContainerMode = (this.defaultSlot?.length ?? 0) > 0;
    const finalColor = this.inverse ? 'inverse' : this.color;
    const classSpinner = classnames(
      `${prefix}`,
      `${prefix}--${this.layout}`,
      `${prefix}--${this.size}`,
      this.inverse && `${prefix}--inverse`,
    );
    const classContainer = classnames(`${prefix}__container`, {
      [`${prefix}__container--fullscreen`]: this.fullscreen,
      [`${prefix}__container--center`]: this.centerIndicator,
      [`${prefix}__container--inverse`]: this.inverse,
    });
    const classBackdrop = classnames(`${prefix}__backdrop`, { [`${prefix}__backdrop--fullscreen`]: this.fullscreen });
    const size = this.size === 'md' ? 16 : 32;
    const strokeWidth = this.size === 'md' ? '4.5' : '3.75';
    const renderIcon = () =>
      finalColor === 'ai' ? (
        <svg
          class={'ks-icon'}
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox={`0 0 48 48`}
          fill="none"
        >
          <path
            d="M4.491 24a19.51 19.51 0 0 0 19.507 19.507A19.51 19.51 0 0 0 43.505 24 19.51 19.51 0 0 0 23.998 4.493"
            stroke="url(#paint0_linear_146525_16462)"
            stroke-width={strokeWidth}
            stroke-linecap="round"
          ></path>
          <animation from="transform: rotate(0)" to="transform: rotate(360deg)"></animation>
          <defs>
            <linearGradient
              id="paint0_linear_146525_16462"
              x1="0"
              y1="28.6758"
              x2="-2.40613e-06"
              y2="-25.0305"
              gradientUnits="userSpaceOnUse"
            >
              <stop stop-color="#31BDB8" />
              <stop offset="0.5" stop-color="#95AEFE" />
              <stop offset="0.995" stop-color="#A1A1FA" />
            </linearGradient>
          </defs>
        </svg>
      ) : (
        <KsIconLoading size={size} class={`${prefix}__indicator`} />
      );

    const renderOverlay = () => {
      if (!this.loading) {
        return null;
      }
      const content = (
        <div class={classContainer}>
          {(this.backdrop || this.fullscreen) && <div class={classBackdrop} part="backdrop" />}
          <div class={classSpinner} part="feedback">
            <slot name="indicator">{renderIcon()}</slot>
            <span class={`${prefix}__description`}>
              <slot name="description"></slot>
            </span>
          </div>
        </div>
      );
      return this.fullscreen ? (
        <ks-overlay mode="modal" open={this.loading}>
          {content}
        </ks-overlay>
      ) : (
        content
      );
    };

    return (
      <Host class="KsSpinner" ks-mode={this.fullscreen ? 'fullscreen' : isContainerMode ? 'container' : 'inline'}>
        {(isContainerMode || this.fullscreen) && renderOverlay()}
        {isContainerMode || this.fullscreen ? (
          <div
            class={`${prefix}__loaded-content`}
            style={{
              opacity: this.loading ? '0' : '1',
            }}
          >
            <slot></slot>
          </div>
        ) : (
          this.loading && (
            <div class={classSpinner} part="feedback">
              <slot name="indicator">{renderIcon()}</slot>
              <span class={`${prefix}__description`}>
                <slot name="description"></slot>
              </span>
            </div>
          )
        )}
      </Host>
    );
  }
}
